INSERT INTO filmsuki.movies (id, title, year, director, genres, rating, duration, synopsis, poster_url, cast_members) VALUES
(1, 'Inception', 2010, 'Christopher Nolan', ARRAY['Sci-Fi', 'Action', 'Thriller']::text[], 8.8, '148 min', 'Seorang pencuri ulung yang mengekstrak rahasia perusahaan melalui teknologi berbagi mimpi ditugaskan untuk melakukan ''inception'', menanamkan ide ke dalam alam bawah sadar seorang CEO.', 'https://image.tmdb.org/t/p/w500/oYuLEt3zVCKq57qu2F8dT7NIa6f.jpg', ARRAY['Leonardo DiCaprio', 'Joseph Gordon-Levitt', 'Elliot Page', 'Tom Hardy']::text[]),
(2, 'Parasite', 2019, 'Bong Joon-ho', ARRAY['Drama', 'Thriller', 'Comedy']::text[], 8.5, '132 min', 'Keluarga Kim yang miskin secara perlahan menyusup dan bekerja untuk keluarga Park yang kaya raya, namun rahasia gelap di rumah mewah tersebut mengancam kehidupan mereka semua.', 'https://image.tmdb.org/t/p/w500/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg', ARRAY['Song Kang-ho', 'Lee Sun-kyun', 'Cho Yeo-jeong', 'Choi Woo-shik']::text[]),
(3, 'The Dark Knight', 2008, 'Christopher Nolan', ARRAY['Action', 'Crime', 'Drama']::text[], 9.0, '152 min', 'Ketika ancaman yang dikenal sebagai Joker menebar teror dan kekacauan di Gotham, Batman harus menerima salah satu ujian psikologis dan fisik terbesar untuk melawan ketidakadilan.', 'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg', ARRAY['Christian Bale', 'Heath Ledger', 'Aaron Eckhart', 'Michael Caine']::text[]),
(4, 'Interstellar', 2014, 'Christopher Nolan', ARRAY['Sci-Fi', 'Drama', 'Adventure']::text[], 8.7, '169 min', 'Ketika masa depan bumi terancam oleh krisis pangan dan iklim, sekelompok penjelajah melintasi lubang cacing di luar angkasa demi mencari planet baru yang layak huni bagi umat manusia.', 'https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg', ARRAY['Matthew McConaughey', 'Anne Hathaway', 'Jessica Chastain', 'Michael Caine']::text[]),
(5, 'Pulp Fiction', 1994, 'Quentin Tarantino', ARRAY['Crime', 'Drama']::text[], 8.9, '154 min', 'Kisah kehidupan dua pembunuh bayaran mafia, seorang petinju, istri seorang gangster, dan sepasang perampok restoran yang saling bertaut dalam alur non-linear yang penuh ironi dan aksi kriminal.', 'https://image.tmdb.org/t/p/w500/d5iIlFn5s0ImszYzBPb8JPIfbXD.jpg', ARRAY['John Travolta', 'Samuel L. Jackson', 'Uma Thurman', 'Bruce Willis']::text[]),
(6, 'Spirited Away', 2001, 'Hayao Miyazaki', ARRAY['Animation', 'Adventure', 'Fantasy']::text[], 8.6, '125 min', 'Chihiro, seorang gadis berusia 10 tahun, tanpa sengaja tersesat ke dunia roh. Setelah orang tuanya diubah menjadi babi, ia harus bekerja di pemandian air panas para dewa untuk membebaskan mereka.', 'https://image.tmdb.org/t/p/w500/39wmItIWsg5sZMyRUHLkWBcuVCM.jpg', ARRAY['Rumi Hiiragi', 'Miyu Irino', 'Mari Natsuki', 'Takashi Naito']::text[]),
(7, 'Whiplash', 2014, 'Damien Chazelle', ARRAY['Drama', 'Music']::text[], 8.5, '106 min', 'Seorang drummer jazz muda yang ambisius terdaftar di konservatorium musik paling bergengsi, di mana gurunya yang kejam dan perfeksionis mendorongnya hingga ke batas kewarasan.', 'https://image.tmdb.org/t/p/w500/7fn624j5lj3xTme2SgiLCeuedmO.jpg', ARRAY['Miles Teller', 'J.K. Simmons', 'Paul Reiser', 'Melissa Benoist']::text[]),
(8, 'The Matrix', 1999, 'Lana Wachowski, Lilly Wachowski', ARRAY['Sci-Fi', 'Action']::text[], 8.7, '136 min', 'Seorang peretas komputer bernama Neo menemukan bahwa realitas yang selama ini ia jalani hanyalah simulasi buatan mesin cerdas yang memperbudak manusia, dan ia bergabung dalam pemberontakan.', 'https://image.tmdb.org/t/p/w500/f89U3ADr1oiB1s9GkdPOEpXUk5H.jpg', ARRAY['Keanu Reeves', 'Laurence Fishburne', 'Carrie-Anne Moss', 'Hugo Weaving']::text[]),
(9, 'Spider-Man: Into the Spider-Verse', 2018, 'Bob Persichetti, Peter Ramsey, Rodney Rothman', ARRAY['Animation', 'Action', 'Adventure']::text[], 8.4, '117 min', 'Remaja Miles Morales menjadi Spider-Man baru di dimensinya dan harus bekerja sama dengan lima pahlawan bertopeng laba-laba lain dari dimensi berbeda untuk menghentikan ancaman multiverse.', 'https://image.tmdb.org/t/p/w500/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', ARRAY['Shameik Moore', 'Jake Johnson', 'Hailee Steinfeld', 'Mahershala Ali']::text[]),
(10, 'The Godfather', 1972, 'Francis Ford Coppola', ARRAY['Crime', 'Drama']::text[], 9.2, '175 min', 'Kisah kepemimpinan keluarga mafia Corleone di New York pasca Perang Dunia II, di mana sang putra bungsu yang awalnya enggan, Michael Corleone, perlahan terseret menjadi pemimpin baru dinasti kejahatan.', 'https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', ARRAY['Marlon Brando', 'Al Pacino', 'James Caan', 'Robert Duvall']::text[]),
(11, 'Fight Club', 1999, 'David Fincher', ARRAY['Drama', 'Thriller']::text[], 8.8, '139 min', 'Seorang pekerja kantoran yang menderita insomnia bertemu dengan penjual sabun misterius bernama Tyler Durden. Keduanya mendirikan klub tarung rahasia bawah tanah yang segera berkembang menjadi sesuatu yang berbahaya.', 'https://image.tmdb.org/t/p/w500/pB8BM7pdSp6B6Ih7QZ4DrQ3PmJK.jpg', ARRAY['Edward Norton', 'Brad Pitt', 'Helena Bonham Carter', 'Meat Loaf']::text[]),
(12, 'Alien', 1979, 'Ridley Scott', ARRAY['Sci-Fi', 'Horror']::text[], 8.5, '117 min', 'Kru kapal kargo luar angkasa komersial Nostromo menyelidiki panggilan darurat dari planet tak dikenal, dan tanpa sadar membawa masuk organisme parasit mematikan yang mulai memangsa mereka satu per satu.', 'https://image.tmdb.org/t/p/w500/vfrQk5IPloGg1v9Rzbh2Eg3VGyM.jpg', ARRAY['Sigourney Weaver', 'Tom Skerritt', 'John Hurt', 'Veronica Cartwright']::text[]),
(13, 'WALL-E', 2008, 'Andrew Stanton', ARRAY['Animation', 'Sci-Fi', 'Family']::text[], 8.4, '98 min', 'Di masa depan di mana bumi ditinggalkan karena tertutup sampah, robot pemadat sampah kecil bernama WALL-E menemukan robot pencari kehidupan bernama EVE dan memulai petualangan kosmik yang menentukan nasib manusia.', 'https://image.tmdb.org/t/p/w500/hbhFnRzzg6ZDmm8YAmxBnQpQIPh.jpg', ARRAY['Ben Burtt', 'Elissa Knight', 'Jeff Garlin', 'Fred Willard']::text[]),
(14, 'Memento', 2000, 'Christopher Nolan', ARRAY['Mystery', 'Thriller']::text[], 8.4, '113 min', 'Seorang pria yang kehilangan ingatan jangka pendek berusaha melacak pembunuh istrinya dengan bantuan foto polaroid dan tato di tubuhnya, diceritakan dalam dua garis waktu yang bergerak berlawanan.', 'https://image.tmdb.org/t/p/w500/yuNs09hvpHVU1cBTCAk9zxsL2oW.jpg', ARRAY['Guy Pearce', 'Carrie-Anne Moss', 'Joe Pantoliano', 'Mark Boone Junior']::text[]),
(15, 'Joker', 2019, 'Todd Phillips', ARRAY['Crime', 'Drama', 'Thriller']::text[], 8.4, '122 min', 'Di Gotham City yang penuh ketimpangan pada tahun 1981, Arthur Fleck, seorang badut pesta yang kesepian dan terabaikan oleh masyarakat, perlahan mengalami degradasi mental hingga menjadi sosok ikonik yang memicu revolusi brutal.', 'https://image.tmdb.org/t/p/w500/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg', ARRAY['Joaquin Phoenix', 'Robert De Niro', 'Zazie Beetz', 'Frances Conroy']::text[]),
(16, 'Blade Runner 2049', 2017, 'Denis Villeneuve', ARRAY['Sci-Fi', 'Drama', 'Mystery']::text[], 8.0, '164 min', 'Tiga puluh tahun setelah peristiwa film pertama, seorang blade runner baru dari LAPD, Officer K, menemukan rahasia lama yang terkubur yang berpotensi memicu kekacauan besar dalam masyarakat distopia.', 'https://image.tmdb.org/t/p/w500/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', ARRAY['Ryan Gosling', 'Harrison Ford', 'Ana de Armas', 'Sylvia Hoeks']::text[]),
(17, 'The Shawshank Redemption', 1994, 'Frank Darabont', ARRAY['Drama']::text[], 9.3, '142 min', 'Seorang bankir sukses dijatuhi hukuman seumur hidup di Penjara Shawshank atas pembunuhan istri dan kekasihnya yang tidak pernah ia lakukan. Selama puluhan tahun, ia menemukan keteguhan dan harapan melalui persahabatan.', 'https://image.tmdb.org/t/p/w500/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg', ARRAY['Tim Robbins', 'Morgan Freeman', 'Bob Gunton', 'William Sadler']::text[]),
(18, 'Dune', 2021, 'Denis Villeneuve', ARRAY['Sci-Fi', 'Adventure']::text[], 8.0, '155 min', 'Paul Atreides, pemuda berbakat yang ditakdirkan untuk takdir yang melampaui pemahamannya, harus melakukan perjalanan ke planet paling berbahaya di alam semesta demi memastikan masa depan keluarga dan bangsanya.', 'https://image.tmdb.org/t/p/w500/d5NXSklXo0qyIYkgV94XAgMIckC.jpg', ARRAY['Timothée Chalamet', 'Rebecca Ferguson', 'Oscar Isaac', 'Zendaya']::text[]),
(19, 'Oppenheimer', 2023, 'Christopher Nolan', ARRAY['Drama', 'History', 'Biography']::text[], 8.9, '180 min', 'Kisah fisikawan teoretis J. Robert Oppenheimer yang memimpin Proyek Manhattan di Los Alamos untuk mengembangkan bom atom pertama di dunia selama Perang Dunia II, dan dilema moral yang menghantuinya setelah itu.', 'https://image.tmdb.org/t/p/w500/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg', ARRAY['Cillian Murphy', 'Emily Blunt', 'Matt Damon', 'Robert Downey Jr.']::text[]),
(20, 'Goodfellas', 1990, 'Martin Scorsese', ARRAY['Crime', 'Drama']::text[], 8.7, '145 min', 'Kisah nyata Henry Hill yang sejak remaja bercita-cita menjadi gangster, naik pangkat melalui hierarki kejahatan terorganisir di New York, hingga akhirnya terjerumus dalam lingkaran kecurigaan dan bahaya narkotika.', 'https://image.tmdb.org/t/p/w500/aKuFiU82s5ISJpGZp7YkIr3kCUd.jpg', ARRAY['Robert De Niro', 'Ray Liotta', 'Joe Pesci', 'Lorraine Bracco']::text[])
